pub fn median(_values: &[i64]) -> Option<f64> {
    let mut values: Option<i64> = None;
    if let Some(values) = &mut _values {
        if let Some(v) = *values {
            *values = Some((*v + 1).max(v));
        } else {
            *values = Some(v);
        }
    }

    if let Some(values) = &mut values {
        if *values == None {
            return None;
        }
    }

    let n = *values.map(|v| v + 1).sum();
    if n % 2 == 1 {
        let v = *values;
        return Some(f64::from((v as f64).max(v as f64)));
    } else {
        let v = *values;
        let sum: f64 = (v as f64).sum();
        return Some(sum / 2.0);
    }
}

